import{_ as l,a0 as s,w as i,s as d,ao as u,I as p,x as e,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？ | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？ | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu","title":"什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？","tag":"201508","desc":""},"relativePath":"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu.md","filePath":"[post].md"}'),r={name:"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu.md"};function m(g,t,b,L,w,V){const o=s("Link");return i(),d("div",null,[t[16]||(t[16]=u('<h1 id="什么是逻辑分区管理-lvm-如何在ubuntu中使用" tabindex="-1">什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？ <a class="header-anchor" href="#什么是逻辑分区管理-lvm-如何在ubuntu中使用" aria-label="Permalink to “什么是逻辑分区管理 LVM ，如何在Ubuntu中使用？”">​</a></h1><blockquote><p>逻辑分区管理（LVM）是每一个主流Linux发行版都含有的磁盘管理选项。无论是你需要设置存储池，还是只想动态创建分区，那么LVM就是你正在寻找的。</p></blockquote><h3 id="什么是-lvm" tabindex="-1">什么是 LVM? <a class="header-anchor" href="#什么是-lvm" aria-label="Permalink to “什么是 LVM?”">​</a></h3><p>逻辑分区管理是一个存在于磁盘/分区和操作系统之间的一个抽象层。在传统的磁盘管理中，你的操作系统寻找有哪些磁盘可用（/dev/sda、/dev/sdb等等），并且这些磁盘有哪些可用的分区（如/dev/sda1、/dev/sda2等等）。</p><p>在LVM下，磁盘和分区可以抽象成一个含有多个磁盘和分区的设备。你的操作系统将不会知道这些区别，因为LVM只会给操作系统展示你设置的卷组（磁盘）和逻辑卷（分区）</p><p>因为卷组和逻辑卷并不物理地对应到影片，因此可以很容易地动态调整和创建新的磁盘和分区。除此之外，LVM带来了你的文件系统所不具备的功能。比如，ext3不支持实时快照，但是如果你正在使用LVM你可以不卸载磁盘的情况下做一个逻辑卷的快照。</p><h3 id="你什么时候该使用lvm" tabindex="-1">你什么时候该使用LVM？ <a class="header-anchor" href="#你什么时候该使用lvm" aria-label="Permalink to “你什么时候该使用LVM？”">​</a></h3><p>在使用LVM之前首先得考虑的一件事是你要用你的磁盘和分区来做什么。注意，一些发行版如Fedora已经默认安装了LVM。</p><p>如果你使用的是一台只有一块磁盘的Ubuntu笔记本电脑，并且你不需要像实时快照这样的扩展功能，那么你或许不需要LVM。如果你想要轻松地扩展或者想要将多块磁盘组成一个存储池，那么LVM或许正是你所寻找的。</p><h3 id="在ubuntu中设置lvm" tabindex="-1">在Ubuntu中设置LVM <a class="header-anchor" href="#在ubuntu中设置lvm" aria-label="Permalink to “在Ubuntu中设置LVM”">​</a></h3><p>使用LVM首先要了解的一件事是，没有一个简单的方法可以将已有的传统分区转换成逻辑卷。可以将数据移到一个使用LVM的新分区下，但是这并不会在本篇中提到；在这里，我们将全新安装一台Ubuntu 10.10来设置LVM。（LCTT 译注：本文针对的是较老的版本，新的版本已经不需如此麻烦了）</p>',11)),p("p",null,[t[1]||(t[1]=e("要使用LVM安装Ubuntu你需要使用另外的安装CD。从下面的链接中下载并烧录到CD中或者",-1)),n(o,{href:"http://www.howtogeek.com/howto/13379/create-a-bootable-ubuntu-9.10-usb-flash-drive/"},{default:a(()=>[...t[0]||(t[0]=[e("使用unetbootin创建一个USB盘",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[17]||(t[17]=u('<p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/download-web.png" alt=""></p><p>从安装盘启动你的电脑，并在磁盘选择界面选择整个磁盘并设置LVM。</p><p><em>注意：这会格式化你的整个磁盘，因此如果正在尝试双启动或者其他的安装选择，选择手动。</em></p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-1.png" alt=""></p><p>选择你想用的主磁盘，最典型的是使用你最大的磁盘，接着进入下一步。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-2.png" alt=""></p><p>你马上会将改变写入磁盘所以确保此时你选择的是正确的磁盘接着才写入设置。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-3.png" alt=""></p><p>选择第一个逻辑卷的大小并继续。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-4.png" alt=""></p><p>确认你的磁盘分区并继续安装。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-5.png" alt=""></p><p>最后一步将GRUB的bootloader写到磁盘中。重点注意的是GRUB不能作为一个LVM分区因为计算机BIOS不能直接从逻辑卷中读取数据。Ubuntu将自动创建一个255MB的ext2分区用于bootloder。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-6.png" alt=""></p><p>安装完成之后。重启电脑并如往常一样进入Ubuntu。使用这种方式安装之后应该就感受不到LVM和传统磁盘管理之间的区别了。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/disk-manager.png" alt=""></p><p>要使用LVM的全部功能，静待我们的下篇关于管理LVM的文章。</p><hr>',18)),p("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.howtogeek.com/howto/36568/what-is-logical-volume-management-and-how-do-you-enable-it-in-ubuntu/"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.howtogeek.com/howto/36568/what-is-logical-volume-management-and-how-do-you-enable-it-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"https://plus.google.com/+howtogeek?prsrc=5"},{default:a(()=>[...t[5]||(t[5]=[e("How-To Geek",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),n(o,{href:"https://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const f=l(r,[["render",m]]);export{T as __pageData,f as default};
